public UberCircle addPuckCircle(CircleOptions circleOptions) {
    UberCircle uberCircleCreate = UberCircle.create(circleOptions, this);
    uberCircleCreate.setRadiusType(1);
    uberCircleCreate.setTrackUserLocation(true);
    uberCircleCreate.setId(this.nativeMapView.addCircle(uberCircleCreate));
    this.annotations.add(uberCircleCreate);
    return uberCircleCreate;
}
